# Re-record the expected values: python3.11 internal/pycompat/testdata/record.py (from the repository root).
"""Write the *_recorded_test.go tables and testdata/diff_fuzz.json from Python 3.11's own behavior."""

import difflib
import json
import os
import random
import re
import struct
import sys
import tempfile
import unicodedata
from pathlib import Path

assert sys.version_info[:2] == (3, 11), "record with Python 3.11, the parity reference"

HERE = Path(__file__).resolve().parent
PACKAGE = HERE.parent
HEADER = "// Code generated by testdata/record.py from Python 3.11; DO NOT EDIT.\n\npackage pycompat\n\n"


def go(value: str) -> str:
    """A Go string literal holding the UTF-8 bytes of value, surrogates included."""
    out = ['"']
    for ch in value:
        code = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif 0x20 <= code < 0x7F or (code >= 0xA0 and ch.isprintable()):
            out.append(ch)
        else:
            out.extend(f"\\x{byte:02x}" for byte in ch.encode("utf-8", "surrogatepass"))
    out.append('"')
    return "".join(out)


def go_list(values) -> str:
    return "[]string{" + ", ".join(go(v) for v in values) + "}"


def write(name: str, body: str) -> None:
    (PACKAGE / name).write_text(HEADER + body, encoding="utf-8")


def ranges(predicate) -> list[tuple[int, int]]:
    found, start = [], None
    for code in range(0x110000):
        if predicate(chr(code)):
            if start is None:
                start = code
        elif start is not None:
            found.append((start, code - 1))
            start = None
    if start is not None:
        found.append((start, 0x10FFFF))
    return found


def go_ranges(name: str, found) -> str:
    rows = "".join(f"\t{{0x{lo:x}, 0x{hi:x}}},\n" for lo, hi in found)
    return f"var {name} = [][2]rune{{\n{rows}}}\n\n"


def record_text() -> None:
    body = []
    split_inputs = [
        "",
        "a",
        "a\n",
        "a\nb",
        "a\r\nb\rc\n",
        "a\n\nb\n\n",
        "\n",
        "a\x0bb\x0cc\x1cd\x1de\x1ef\x1fg",
        "a\x85b\u2028c\u2029d",
        "a\r\r\nb",
        "line\u2028",
        "tab\tand space ",
    ]
    rows = "".join(
        f"\t{{{go(s)}, {go_list(s.splitlines())}, {go_list(s.splitlines(keepends=True))}}},\n" for s in split_inputs
    )
    body.append(f"var splitLinesCases = []struct {{\n\tin       string\n\tlines    []string\n\tkeepEnds []string\n}}{{\n{rows}}}\n\n")

    strip_inputs = [
        "",
        "  a b  ",
        "\t\n\x0b\x0c\r a \r\n",
        "\x1c\x1d\x1e\x1fa\x1f\x1e\x1d\x1c",
        "\x85\xa0a\u3000\u2028",
        "\u200ba\u200b",
        "\u1680\u2000\u200a\u202f\u205fa",
        "\x00a\x00",
        "é",
    ]
    rows = "".join(f"\t{{{go(s)}, {go(s.strip())}, {go(s.lstrip())}, {go(s.rstrip())}}},\n" for s in strip_inputs)
    body.append(f"var stripCases = []struct{{ in, strip, lstrip, rstrip string }}{{\n{rows}}}\n\n")

    read_inputs = [b"a\r\nb\rc", b"a\nb\n", b"\r\r\n\n", b"caf\xc3\xa9\r\n", b"\xef\xbb\xbfbom\n", b"no newline"]
    rows = []
    with tempfile.TemporaryDirectory() as tmp:
        for raw in read_inputs:
            path = Path(tmp, "file")
            path.write_bytes(raw)
            text = path.read_text(encoding="utf-8")
            rows.append(f"\t{{{go(raw.decode('utf-8'))}, {go(text)}, {go_list(text.splitlines(keepends=True))}}},\n")
    body.append(
        "var readTextCases = []struct {\n\tfile  string\n\ttext  string\n\tlines []string\n}{\n" + "".join(rows) + "}\n\n"
    )

    invalid = [b"\xff", b"caf\xe9", b"\xed\xa0\x80", b"\xc0\xaf", b"ok\x80"]
    for raw in invalid:
        try:
            raw.decode("utf-8")
        except UnicodeDecodeError:
            continue
        raise AssertionError(raw)
    body.append("var invalidUTF8Files = []string{" + ", ".join(go_bytes(raw) for raw in invalid) + "}\n\n")

    word = re.compile(r"\w")
    space = re.compile(r"\s")
    assert ranges(lambda c: bool(space.match(c))) == ranges(str.isspace)
    body.append(go_ranges("pythonSpace", ranges(str.isspace)))
    body.append(go_ranges("pythonWord", ranges(lambda c: bool(word.match(c)))))
    body.append(go_ranges("pythonLineBreak", ranges(lambda c: len(f"a{c}b".splitlines()) == 2)))
    body.append(go_ranges("pythonPrintable", ranges(str.isprintable)))
    body.append(go_ranges("pythonAssigned", ranges(lambda c: unicodedata.category(c) != "Cn")))

    patterns = {
        "wezterm builder": (r"^local\s+(\w+)\s*=\s*wezterm\.config_builder\(\)\s*$", re.MULTILINE),
        "wezterm return": (r"^return\s+(\w+)\s*$", re.MULTILINE),
        "wezterm color scheme": (r"^\s*(?:\w+\.)?color_scheme\s*=", 0),
        "managed id comment": (r"^# sf2-themes:\s+(\S+)\s*$", 0),
    }
    inputs = [
        "local config = wezterm.config_builder()",
        "local café = wezterm.config_builder()",
        "local 設定 = wezterm.config_builder()",
        "local ⅷ_2 = wezterm.config_builder()",
        "local\xa0cfg\u3000=\u2003wezterm.config_builder()\u2028",
        "local cfg-x = wezterm.config_builder()",
        "-- header\nlocal c = wezterm.config_builder()\nreturn c\n",
        "local c =\n  wezterm.config_builder()",
        "return café",
        "return c\xa0",
        "  café.color_scheme = 'x'",
        "\u3000color_scheme=",
        "# sf2-themes: sf2-ryu",
        "# sf2-themes:\xa0sf2-ryu\u2003",
        "# sf2-themes:\u200bsf2-ryu",
        "# sf2-themes: sf2-ryu extra",
    ]
    rows = []
    for name, (pattern, flags) in patterns.items():
        compiled = re.compile(pattern, flags)
        for text in inputs:
            found = compiled.search(text)
            if found is None:
                rows.append(f"\t{{{go(name)}, {go(text)}, false, \"\"}},\n")
            else:
                group = found.group(1) if compiled.groups else found.group(0)
                rows.append(f"\t{{{go(name)}, {go(text)}, true, {go(group)}}},\n")
    body.append(
        "var regexCases = []struct {\n\tpattern string\n\ttext    string\n\tmatched bool\n\tgroup   string\n}{\n"
        + "".join(rows)
        + "}\n"
    )
    write("text_recorded_test.go", "".join(body))


def go_bytes(raw: bytes) -> str:
    return '"' + "".join(chr(b) if 0x20 <= b < 0x7F and b not in b'"\\' else f"\\x{b:02x}" for b in raw) + '"'


def record_path() -> None:
    from pathlib import PurePosixPath

    body = []
    joins = [
        ["a//b/./c"],
        ["a/../b"],
        ["a", "../b"],
        ["a", "..", "b"],
        [""],
        ["."],
        ["./"],
        ["a/"],
        ["/"],
        ["//"],
        ["///"],
        ["//a//b"],
        ["///a"],
        ["a", "/b", "c"],
        ["a", "//b"],
        ["/home/u", ".config", "herdr-app"],
        ["", "herdr-app"],
        [".", "settings.json"],
        ["~", "x"],
        ["a", ""],
        ["a/./", "./b/."],
        ["..", ".."],
    ]
    rows = "".join(f"\t{{{go_list(parts)}, {go(str(PurePosixPath(*parts)))}}},\n" for parts in joins)
    body.append(f"var pathCases = []struct {{\n\tparts []string\n\twant  string\n}}{{\n{rows}}}\n\n")

    names = ["a/b/c.txt", "c.txt", "/", "//", ".", "", "/a", "a/", "a/..", "../a", "~/x/settings.json", "//a"]
    rows = []
    for raw in names:
        p = PurePosixPath(raw)
        with_name = go(str(p.with_name("n.bak"))) if p.name else '""'
        rows.append(f"\t{{{go(raw)}, {go(p.name)}, {go(str(p.parent))}, {with_name}}},\n")
    body.append(
        "var namePartsCases = []struct{ path, name, parent, withName string }{\n" + "".join(rows) + "}\n\n"
    )

    homes = ["/home/u", "/home/u/", "", "/", "rel/dir", "//net/home", "/a//b/./c"]
    inputs = ["~", "~/", "~/x", "~/x/../y", "x/~", "/~", "~nosuchuser-sf2/x", "a//b"]
    rows = []
    saved = os.environ.get("HOME")
    try:
        for home in homes:
            os.environ["HOME"] = home
            for raw in inputs:
                try:
                    rows.append(f"\t{{{go(home)}, {go(raw)}, {go(str(Path(raw).expanduser()))}, false}},\n")
                except RuntimeError:
                    rows.append(f"\t{{{go(home)}, {go(raw)}, \"\", true}},\n")
        for home in ["~bad"]:
            os.environ["HOME"] = home
            try:
                Path("~/x").expanduser()
                raise AssertionError("expected RuntimeError")
            except RuntimeError:
                rows.append(f"\t{{{go(home)}, \"~/x\", \"\", true}},\n")
    finally:
        if saved is None:
            del os.environ["HOME"]
        else:
            os.environ["HOME"] = saved
    body.append(
        "var expandUserCases = []struct {\n\thome    string\n\tpath    string\n\twant    string\n\twantErr bool\n}{\n"
        + "".join(rows)
        + "}\n\n"
    )

    # Layout shared with resolveLayout in path_test.go; "@" stands for the resolved temporary root.
    inputs = [
        "link/file",
        "link/../x",
        "link/..",
        "real/../real/file",
        "missing/../y",
        "dangling/q",
        "chain",
        "chain/../z",
        "abs/file",
        "./link//file/",
        "loop1/z",
        "uplink/real/file",
        "missing/new.txt",
        "@/link/file",
        "@/real/./file",
    ]
    rows = []
    cwd = os.getcwd()
    with tempfile.TemporaryDirectory() as tmp:
        root = os.path.realpath(tmp)
        os.mkdir(f"{root}/real")
        Path(f"{root}/real/file").write_text("x")
        os.symlink("real", f"{root}/link")
        os.symlink(f"{root}/real", f"{root}/abs")
        os.symlink("loop2", f"{root}/loop1")
        os.symlink("loop1", f"{root}/loop2")
        os.symlink("missing/target", f"{root}/dangling")
        os.symlink("link/file", f"{root}/chain")
        os.symlink("real/..", f"{root}/uplink")
        os.chdir(root)
        try:
            for raw in inputs:
                resolved = str(Path(os.path.realpath(raw.replace("@", root))))
                assert resolved.startswith(root)
                rows.append(f"\t{{{go(raw)}, {go('@' + resolved[len(root):])}}},\n")
        finally:
            os.chdir(cwd)
    body.append("var resolveCases = []struct{ path, want string }{\n" + "".join(rows) + "}\n")
    write("path_recorded_test.go", "".join(body))


def record_json() -> None:
    body = []
    documents = [
        "{}",
        "[]",
        "  {\n}  ",
        '{"a" : [ ] , "b":{}}',
        '{"b": 1, "a": {"x": []}, "c": "é"}',
        '{"a": 1, "b": 2, "a": 3}',
        '{"a": {"x": 1}, "a": [true]}',
        "true",
        "false",
        "null",
        "1.50",
        "1E5",
        "1e16",
        "1e15",
        "1e-5",
        "0.0001",
        "1E+2",
        "2.5e-3",
        "-0",
        "-0.0",
        "0",
        "100",
        "1.0",
        "3.14159",
        "0.1",
        "123456789012345678901234567890",
        "-123456789012345678901234567890",
        "1e400",
        "-1e400",
        "1e-400",
        "NaN",
        "Infinity",
        "-Infinity",
        "[NaN, Infinity, -Infinity]",
        '"é"',
        '"\\u00e9"',
        '"<>&/"',
        '"\\/"',
        '"\\b\\f\\n\\r\\t\\"\\\\"',
        '"\\u0000\\u001f\\u007f"',
        '"\x7f"',
        '"\U0001F600"',
        '"\\ud83d\\ude00"',
        '"\\ud800"',
        '"\\udc00x"',
        '"\\ud800\\u0041"',
        '"\\ud800\\ud800\\udc00"',
        '{"\\ud800": "\\udfff"}',
        '"\u2028\u0085"',
        '"\\u00E9"',
        '{"k": [1, [2, {}], {"z": null}]}',
        "[1,]",
        '{"a": 1,}',
        "[,]",
        "{,}",
        "01",
        "1.",
        ".5",
        "-",
        "+1",
        "-NaN",
        "nan",
        "infinity",
        "nul",
        "tru",
        "",
        "  ",
        "\ufeff{}",
        "[1, 2",
        '{"a"',
        '{"a" 1}',
        '{"a": 1 "b": 2}',
        "{1: 2}",
        '"abc',
        '"abc\\',
        '"\\x"',
        '"\\u12"',
        '"\\u12G4"',
        '"\\ud800\\u12G4"',
        '"a\x01"',
        '"tab\there"',
        "1 2",
        "[1] x",
        "1e",
        "1e+",
        "1.5e",
        "-Infinityx",
        "[\n  1,\n  oops\n]",
        "\t[\r\n]",
        "\xa0[]",
    ]
    rows = []
    for doc in documents:
        try:
            value = json.loads(doc)
        except json.JSONDecodeError as error:
            rows.append(f"\t{{{go(doc)}, \"\", \"\", {go(str(error))}}},\n")
            continue
        rows.append(
            f"\t{{{go(doc)}, {go(json.dumps(value, indent=2))}, {go(json.dumps(value, indent=2, ensure_ascii=False))}, \"\"}},\n"
        )
    body.append(
        "var jsonCases = []struct {\n\tdoc     string\n\tascii   string\n\tunicode string\n\terr     string\n}{\n"
        + "".join(rows)
        + "}\n\n"
    )

    # Mirrors TestObjectKeepsKeyOrder in json_test.go.
    data = json.loads('{"b": 1, "a": {"x": []}, "c": "é"}')
    data["a"] = "changed"
    data["z"] = {"dark": "sf2-ryu", "light": "sf2-ryu-light"}
    data["b"] = [1, 2.5, None, False]
    body.append(f"const objectEditWant = {go(json.dumps(data, indent=2))}\n\n")

    rng = random.Random(1987)
    floats = [0.0, -0.0, 1.0, 0.1, 1e16, 1e15, 9999999999999998.0, 1e-4, 1e-5, 5e-324, 1.7976931348623157e308, 2.0**53, 123456.789]
    while len(floats) < 1000:
        (value,) = struct.unpack("<d", rng.getrandbits(64).to_bytes(8, "little"))
        if value == value and abs(value) != float("inf"):
            floats.append(value)
    for _ in range(300):
        floats.append(rng.uniform(-1e6, 1e6))
        floats.append(round(rng.uniform(-1000, 1000), rng.randint(0, 6)))
    rows = "".join(f"\t{{0x{struct.unpack('<Q', struct.pack('<d', v))[0]:016x}, {go(repr(v))}}},\n" for v in floats)
    body.append(f"var floatReprCases = []struct {{\n\tbits uint64\n\twant string\n}}{{\n{rows}}}\n")
    write("json_recorded_test.go", "".join(body))


def record_repr() -> None:
    inputs = [
        "",
        "abc",
        "it's",
        'say "hi"',
        "both ' and \"",
        "back\\slash",
        "tab\tnl\ncr\r",
        "\x00\x1b[0m\x7f",
        "\x85\xa0\xad",
        "café 名前",
        "\u200b\u2028\u2029\u3000",
        "\ue000\U0010ffff",
        "\U0001F600\U000e0001",
        "#GGGGGG",
        "\ufeff",
    ]
    rows = "".join(f"\t{{{go(s)}, {go(repr(s))}}},\n" for s in inputs)
    write("repr_recorded_test.go", f"var reprCases = []struct{{ in, want string }}{{\n{rows}}}\n")


def diff_text(before: list[str], after: list[str], from_name: str, to_name: str) -> str:
    return "".join(difflib.unified_diff(before, after, fromfile=from_name, tofile=to_name))


def record_diff() -> None:
    def lines(text: str) -> list[str]:
        return text.splitlines(keepends=True)

    cases = {
        "new file": (None, "a\nb\n"),
        "new empty file": (None, ""),
        "unchanged": ("a\nb\n", "a\nb\n"),
        "one line changed": ("a\nb\nc\n", "a\nB\nc\n"),
        "last line without newline": ("a\nb", "a\nc"),
        "newline added at end": ("a\nb", "a\nb\n"),
        "newline removed at end": ("a\nb\n", "a\nb"),
        "emptied": ("a\nb\n", ""),
        "far apart edits": ("".join(f"{i}\n" for i in range(30)), "".join(f"{i if i not in (2, 25) else 'x'}\n" for i in range(30))),
        "edits seven apart": ("".join(f"{i}\n" for i in range(20)), "".join(f"{i if i not in (5, 12) else 'x'}\n" for i in range(20))),
        "edits six apart": ("".join(f"{i}\n" for i in range(20)), "".join(f"{i if i not in (5, 11) else 'x'}\n" for i in range(20))),
        "unicode line breaks": ("a\u2028b\x0cc\n", "a\u2028B\x0cc\n"),
    }
    # Two 300-line files where "}" fills more than 1% of the lines, so autojunk drops it from the index.
    before = []
    for i in range(300):
        before.append("}\n" if i % 5 == 4 else f"  value_{i} = {i}\n")
    after = list(before)
    after[10] = "  value_10 = changed\n"
    del after[50:53]
    after.insert(120, "}\n")
    after.insert(121, "}\n")
    after[200] = "}\n"
    after[260:262] = ["  inserted\n"]
    # Rewrite a stretch so only its "}" lines still match; autojunk turns it into one replaced block.
    for i in range(130, 170):
        if after[i] != "}\n":
            after[i] = f"  other_{i}\n"
    autojunk = difflib.SequenceMatcher(None, before, after).get_opcodes()
    assert autojunk != difflib.SequenceMatcher(None, before, after, autojunk=False).get_opcodes()
    cases["300 lines with a repeated line"] = ("".join(before), "".join(after))

    rows = []
    for name, (old, new) in cases.items():
        before = lines(old) if old is not None else []
        from_name = "/dev/null" if old is None else "/tmp/config/settings.json"
        want = diff_text(before, lines(new), from_name, "/tmp/config/settings.json")
        rows.append(f"\t{{{go(name)}, {go_list(before)}, {go_list(lines(new))}, {go(from_name)}, {go(want)}}},\n")
    write(
        "diff_recorded_test.go",
        "var diffCases = []struct {\n\tname   string\n\tbefore []string\n\tafter  []string\n\tfrom   string\n\twant   string\n}{\n"
        + "".join(rows)
        + "}\n",
    )

    rng = random.Random(2026)
    fuzz = []
    for index in range(300):
        long = index % 10 == 0
        size = rng.randint(200, 260) if long else rng.randint(0, 40)
        alphabet = "abcdefgh"[: rng.randint(2, 8)]
        a = [rng.choice(alphabet) + "\n" for _ in range(size)]
        b = list(a)
        for _ in range(rng.randint(0, 12 if long else 6)):
            op = rng.choice("rid")
            at = rng.randint(0, len(b))
            if op == "i" or not b:
                b[at:at] = [rng.choice(alphabet) + "\n" for _ in range(rng.randint(1, 4))]
            elif op == "d":
                del b[at : at + rng.randint(1, 4)]
            else:
                b[at : at + 1] = [rng.choice(alphabet) + "\n"]
        if b and rng.random() < 0.2:
            b[-1] = b[-1].rstrip("\n")
        fuzz.append({"a": "".join(a), "b": "".join(b), "diff": diff_text(a, b, "old", "new")})
    (HERE / "diff_fuzz.json").write_text("[\n" + ",\n".join(json.dumps(case) for case in fuzz) + "\n]\n", encoding="utf-8")


record_text()
record_path()
record_json()
record_repr()
record_diff()
